import{_ as t,o,c as a,a0 as n}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse('{"title":"Commands","description":"The bun commands of the repository, the shared control gallery, and the guide screenshots.","frontmatter":{"title":"Commands","description":"The bun commands of the repository, the shared control gallery, and the guide screenshots."},"headers":[],"relativePath":"development/commands.md","filePath":"development/commands.md"}'),r={name:"development/commands.md"};function d(s,e,c,h,l,i){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>bun run dev</code></td><td>Start the control plane in watch mode</td></tr><tr><td><code>bun test</code></td><td>Run the full test suite</td></tr><tr><td><code>bun run gallery</code></td><td>Run the shared control gallery, using the real modules</td></tr><tr><td><code>bun run lint</code></td><td>Lint and check formatting with Biome</td></tr><tr><td><code>bun run fmt</code></td><td>Lint, format, and fix with Biome</td></tr><tr><td><code>bun run typecheck</code></td><td>Typecheck with TypeScript</td></tr><tr><td><code>bun run screenshots</code></td><td>Regenerate the guide screenshots from fixture state</td></tr></tbody></table><p><code>bun run dev</code> runs the source tree; it reads <code>config/development.toml</code> through <code>--config</code> and watches the tree while it runs.</p><h2 id="shared-control-gallery" tabindex="-1">Shared control gallery <a class="header-anchor" href="#shared-control-gallery" aria-label="Permalink to &quot;Shared control gallery&quot;">​</a></h2><p><code>bun run gallery</code> opens the shared control gallery: every control the control plane owns, drawn by the production modules and answering the production keys. <code>Tab</code> shows the next example, and each one names its own state - normal and focused, invalid, unavailable, loading, Type-ahead search, and narrow. Pass an example name to land on it: <code>bun run gallery -- fields</code>. The gallery reads no config file, opens no state, and starts no Agent, and the same examples are exercised by <code>bun test</code>, so a gallery row cannot become an imitation of the control. See <a href="./shared-controls.html">the shared control standard</a>.</p><h2 id="regenerating-the-screenshots" tabindex="-1">Regenerating the screenshots <a class="header-anchor" href="#regenerating-the-screenshots" aria-label="Permalink to &quot;Regenerating the screenshots&quot;">​</a></h2><p><code>bun run screenshots</code> rebuilds the images the <a href="./../operation/main-view.html">operation guide</a> shows: the fixture world, the production binary on a pseudo-terminal, the production keys, and the cell-grid render. The drift test in <code>bun test</code> reruns the same path and fails when a committed image no longer matches the screen, so a screen change always lands with its image.</p>',7)])])}const p=t(r,[["render",d]]);export{u as __pageData,p as default};
